 void approvalIsAlwaysPlainText(){WirePeer peer;const auto expires=QDateTime::currentMSecsSinceEpoch()+600000;QJsonObject op{{"id","operation"},{"conversationId","1"},{"fingerprint","fingerprint"},{"tool","shell_run"},{"risk","unrestricted_shell"},{"status","awaiting_approval"},{"createdAt",QDateTime::currentMSecsSinceEpoch()-120000},{"attempt",1},{"summary","Long running local fixture"},{"targets",QJsonArray{"/private/fixture"}},{"output",""},{"truncated",false},{"approvalExpiresAt",expires}};peer.operations={op};const QString script="printf '<img src=\"file:///private/never-read\">'\n# literal $(never execute)";peer.details={{"operationId","operation"},{"fingerprint","fingerprint"},{"risk","unrestricted_shell"},{"expiresAt",expires},{"request",QJsonObject{{"tool","shell_run"},{"args",QJsonObject{{"cwd","/private/fixture"},{"script",script},{"timeoutMs",QJsonValue::Null}}}}}};IpcBridge bridge(peer.home.filePath("outbox.json"));bridge.connectToAgent(peer.home.filePath("socket"));QTRY_COMPARE(bridge.approvals()->rowCount(),1);QQmlApplicationEngine engine;auto*w=load(engine,bridge);QVERIFY(w);QVERIFY(QTest::qWaitForWindowExposed(w));bridge.loadApprovalDetails("operation","fingerprint");auto*dialog=w->findChild<QObject*>("approvalDialog");QVERIFY(dialog);QVERIFY(QMetaObject::invokeMethod(dialog,"open"));QVERIFY2(QTest::qWaitFor([&]{return bridge.approvals()->canDecide();},2000),qPrintable(QString("connection=%1 error=%2 selected=%3 complete=%4 cache=%5 dialog=%6").arg(bridge.connectionState(),bridge.error(),bridge.approvals()->selectedId()).arg(bridge.approvals()->document()->complete()).arg(bridge.approvals()->document()->displayed()).arg(dialog->property("visible").toBool())));QTest::qWait(50);QList<QQuickItem*>items;visualItems(w->contentItem(),items);bool saw=false;for(auto*i:items){const auto text=i->property("text").toString();if(text.contains("never execute")){saw=true;QCOMPARE(i->property("textFormat").toInt(),int(Qt::PlainText));}}QVERIFY(saw);auto*approve=w->findChild<QQuickItem*>("approveOnce");QVERIFY(approve);QVERIFY(!approve->hasActiveFocus());const auto dir=qEnvironmentVariable("TILDE_UI_CAPTURE_DIR");if(!dir.isEmpty())QVERIFY(w->grabWindow().save(dir+"/exact-approval.png"));QCOMPARE(peer.decisions.size(),0);QCOMPARE(peer.submissions.size(),0);}
 void noDeadlineFromRetainedCanonicalEnvelope(){QTemporaryDir d;ApprovalModel model;model.setScope("1");model.setCacheDirectory(d.filePath("review"));const auto expires=QDateTime::currentMSecsSinceEpoch()+600000;QJsonObject op{{"id","operation"},{"conversationId","1"},{"fingerprint","fingerprint"},{"tool","shell_run"},{"risk","unrestricted_shell"},{"status","awaiting_approval"},{"approvalExpiresAt",expires}};model.apply({{"operations",QJsonArray{op}}});QVERIFY(model.select("operation","fingerprint"));const auto request=QJsonObject{{"tool","shell_run"},{"args",QJsonObject{{"cwd","/private"},{"script","sleep fixture"},{"timeoutMs",QJsonValue::Null}}}};const auto raw=QJsonDocument(QJsonObject{{"operationId","operation"},{"fingerprint","fingerprint"},{"request",request},{"risk","unrestricted_shell"},{"expiresAt",expires}}).toJson(QJsonDocument::Compact);QVERIFY(model.setManifest({{"conversationId","1"},{"operationId","operation"},{"fingerprint","fingerprint"},{"payloadId","payload"},{"sha256",QString::fromLatin1(QCryptographicHash::hash(raw,QCryptographicHash::Sha256).toHex())},{"bytes",raw.size()},{"chunkBytes",32768},{"risk","unrestricted_shell"},{"expiresAt",expires}}));QVERIFY(model.acceptChunk({{"payloadId","payload"},{"offset",0},{"text",QString::fromUtf8(raw)}}));QVERIFY(model.property("deadlineLabel").toString().contains("No time limit"));QVERIFY(model.detailsText().contains("null"));QVERIFY(!model.canDecide());}
